  "c2_evidence": {
    "passed": false,
    "reason": "The rationale says the subscription lacks a concrete demo today. The s16 paywall evidence does not establish that no demo exists elsewhere, and the claim is phrased as an app-wide fact rather than something not seen."
  },
  "c4_protects_subscription": {
